import {
  PlaneGeometry,
  Mesh,
  MeshBasicNodeMaterial,
  TextureLoader,
} from 'three/webgpu';
import { texture2D, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  // --- Load texture from the provided imageUrl ---
  const textureLoader = ctx.textureLoader || new TextureLoader();
  const texture = textureLoader.load(config.assets.imageUrl);
  texture.wrapS = texture.wrapT = 1000; // ClampToEdge (using three.js integer constant)
  texture.anisotropy = 16; // optional, for sharp edges

  // --- Determine plane size from atlas region aspect ratio (512x320) ---
  const aspect = 512 / 320; // ≈1.6
  const width = 1.6;
  const height = width / aspect; // ≈1.0

  // --- Build material with TSL nodes ---
  const material = new MeshBasicNodeMaterial();
  material.colorNode = texture2D(texture, uv());

  // --- Geometry and mesh ---
  const geometry = new PlaneGeometry(width, height);
  const mesh = new Mesh(geometry, material);

  // --- Apply placement from config.scenePosition ---
  const pos = config.scenePosition;
  mesh.position.set(pos.x, pos.y, pos.z);
  mesh.rotation.set(pos.rotX || 0, pos.rotY || 0, pos.rotZ || 0);
  if (pos.scale !== undefined) {
    mesh.scale.set(pos.scale.x, pos.scale.y, pos.scale.z);
  }

  // --- Apply all cinematic primitives (none in spec) ---
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      ctx.primitives[prim.name](mesh, prim.params);
    });
  }

  // --- Attach event handlers (none) ---
  mesh.userData.handlers = {};

  // --- Cleanup ---
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    // If any GSAP timeline were present, kill it here
    if (mesh.userData.timeline) {
      mesh.userData.timeline.kill();
    }
  };

  return mesh;
}
